import{_ as i,l,o as e,c as n,v as o,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"摩尔定律的光刻视角","description":"","frontmatter":{"title":"摩尔定律的光刻视角","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/moore-litho-view.md","filePath":"litho/moore-litho-view.md","lastUpdated":1789023840000}'),E={name:"litho/moore-litho-view.md"};function c(_,a,A,m,u,T){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="摩尔定律的光刻视角" tabindex="-1">摩尔定律的光刻视角 <a class="header-anchor" href="#摩尔定律的光刻视角" aria-label="Permalink to &quot;摩尔定律的光刻视角&quot;">​</a></h1><div class="epigraph"><p>晶体管变便宜，长期靠的是可印密度上升；当单次光学到顶，多重、EUV 与助推器接过「每两年」这根棒，账单改记在步骤与随机上。</p><footer>—— 对照 Moore 原文的经济命题与其后光刻接棒（RET、浸没、多重、EUV）的产业史</footer></div><p><a href="/litho/fab-capex">上一课</a>说明支票变大。缺口是为什么还要开：密度经济。本课钉摩尔定律的光刻视角。谁能卖这些机台（单一来源），留给[下一课](/litho/supply-chain-single-source）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Moore 1965 年的观察是组件成本随集成度降。光刻是把更多组件印进同一面积的主杠杆。波长与 NA 的台阶（g/i 线 → KrF → ArF → 浸没 → EUV）加上 \\(k_1\\) 与分解，构成时间轴。本课不重推瑞利，只钉：每个台阶都是「继续让面积成本下降」的工程，而不是自然定律保证永远下降。</p><p>缺口是<strong>经济命题 vs 分辨率公式</strong>。把摩尔当物理定律，会在随机悬崖上假装还有下一代波长自动出现。</p><h3 id="dennard-之后" tabindex="-1">Dennard 之后 <a class="header-anchor" href="#dennard-之后" aria-label="Permalink to &quot;Dennard 之后&quot;">​</a></h3><p>电压与频率缩放停得比密度早。光刻仍在挤密度，功耗与设计（助推器、架构）接过另一部分。密度度量课已警告口径。</p><p><span class="marginnote">「摩尔死了」的讨论常混：成本每晶体管、性能、还是节点名。光刻视角只负责可印密度与层成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读历史：每代光刻如何推迟「面积成本上升」。读现在：交叉课的层策略是否还能让每晶体管成本降。读未来：Hyper-NA 之后课。与 IRDS：表是需求，摩尔是经济愿望，二者可脱节。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每晶体管成本 ≈ 每晶圆成本 /（密度 × 良率 × 面积利用率）。光刻同时进分子（层成本）与分母（密度、良率）。多重提高密度也提高分子；EUV 可能降分子中的步骤、抬随机对分母的威胁。净效果是经验问题，不是口号。</p>',13)),(e(),s(p,null,{default:t(()=>[h(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DENS%5B%22%E5%8F%AF%E5%8D%B0%E5%AF%86%E5%BA%A6%22%5D%20--%3E%20CPT%5B%22%E6%AF%8F%E6%99%B6%E4%BD%93%E7%AE%A1%E6%88%90%E6%9C%AC%22%5D%0A%20%20COST%5B%22%E6%AF%8F%E6%99%B6%E5%9C%86%E6%88%90%E6%9C%AC%22%5D%20--%3E%20CPT%0A%20%20Y%5B%22%E8%89%AF%E7%8E%87%22%5D%20--%3E%20CPT%0A%20%20LITH%5B%22%E6%B3%A2%E9%95%BF%20NA%20%E5%88%86%E8%A7%A3%22%5D%20--%3E%20DENS%0A%20%20LITH%20--%3E%20COST%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测摩尔是否继续。不把 CPU 性能当光刻成就。本课不讨论非光刻的 3D 封装全史——后课会遇键合。</p><p>后课默认：密度经济依赖可交付工具链；下一课工具链高度集中的风险。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>摩尔是成本–密度经济命题；光刻用波长、NA、分解、助推器接棒。</li><li>每晶体管成本同时含层成本与良率，多重与 EUV 两边都动。</li><li>不是保证永远下降的物理定律。</li><li>出处：Moore 1965 经济观察；光刻世代接棒的产业史。</li></ul>',5))])}const D=i(E,[["render",c]]);export{C as __pageData,D as default};
